/**
 * All amounts are integer minor units of `currency` (e.g. cents for USD).
 * Never store fractional amounts — all money arithmetic is integer-only.
 * Display code divides by 10^(currency decimals) at render time.
 */
export interface MoneyBreakdown {
  itemSubtotal: number;
  shippingAmount: number;
  taxAmount: number;
  applicationFeeAmount: number;
  currency: string;
}

export interface PackageDimensionsMm {
  lengthMm: number;
  widthMm: number;
  heightMm: number;
}

/**
 * The longest title a listing may carry, counted the way `String.length` and the forms' `maxLength`
 * count (UTF-16 code units). The sell forms already stopped at 200, but nothing server-side did, so
 * `/api/v1/listings`, the unversioned routes, the AI tools and the MCP tools could store a 203-character
 * title that no form could re-save. The domain asserts it on create and on a title edit; the v1
 * request schemas carry it as `maxLength` so an API caller gets a 400 that names the limit.
 */
export const LISTING_TITLE_MAX_LENGTH = 200;

/**
 * The category path a listing gets when no caller supplied one.
 *
 * Marka has no category table — a `categoryPath` is a free-form, slash-delimited string that
 * exists exactly as long as an active listing carries it (see countActiveListingsByCategory).
 * So this is a convention, not a foreign key, and the ONE place it is written: the web
 * draft-input mapper and the AI listing runtime both read it, pinned by a test, because two
 * copies already drifted apart once ("general" vs "general/misc").
 */
export const DEFAULT_CATEGORY_PATH = "general";

/** The category path an external-channel import falls back to when the title matches no keyword. */
export const IMPORTED_CATEGORY_PATH = "misc/imported";

/**
 * The shape every `categoryPath` must have: lowercase alphanumeric parts joined by "-" or "/", no
 * leading or trailing separator, at most 64 characters, and **no "/"-separated segment made only of
 * digits**.
 *
 * That last clause is the one doing the real work. The rest of the rule already lived on the
 * `/market/c/<path>` route as a cheap gate on junk URLs, but it happily accepts "175759" and
 * "ebay/175759" — which is exactly what an opaque external-marketplace category id looks like, and
 * exactly what reached two production rows through write doors that validated nothing. A digits-only
 * segment is an id, not a taxonomy name; a real path always names something.
 *
 * It splits on "/" ONLY: a hyphen joins words inside one segment, so "nintendo-64" and "ps-5" are
 * ordinary taxonomy names, while "nintendo/64" claims a numeric child category and is not.
 *
 * `CATEGORY_PATH_PATTERN` is exported so request schemas can chain it as a `.regex()` — that lands
 * the shape in the generated OpenAPI/MCP documents as a machine-readable `pattern`, where a bare
 * `.refine` would only ever produce "Invalid input".
 */
export const CATEGORY_PATH_MAX_LENGTH = 64;
export const CATEGORY_PATH_PATTERN = /^[a-z0-9]+(?:[-/][a-z0-9]+)*$/;
const ALL_DIGITS_PATTERN = /^[0-9]+$/;

export function isPlausibleCategoryPath(value: string): boolean {
  if (!CATEGORY_PATH_PATTERN.test(value) || value.length > CATEGORY_PATH_MAX_LENGTH) return false;
  return !value.split("/").some((segment) => ALL_DIGITS_PATTERN.test(segment));
}

/** The rejection message every door gives back — an API 400, and the AI tool's retry signal. */
export const CATEGORY_PATH_MESSAGE =
  'Must be a lowercase slash-delimited taxonomy path such as "electronics/cameras" — never a ' +
  "numeric marketplace category id.";

export interface Listing {
  id: string;
  sellerAccountId: string;
  authority: ListingAuthority;
  status: ListingStatus;
  inventoryType: InventoryType;
  quantityTotal: number;
  quantityReserved: number;
  categoryPath: string;
  condition: ListingCondition;
  title: string;
  description: string;
  attributes: JsonValue;
  imageUrls: string[];
  brand: string | null;
  /** UPC, EAN, ISBN, or other GTIN — stored as digits-only string. */
  gtin: string | null;
  packageWeightGrams: number | null;
  packageDimensionsMm: PackageDimensionsMm | null;
  /**
   * ISO 3166-1 alpha-2 (uppercase) country of manufacture; null = not specified. Easyship reads it
   * as the item's `origin_country_alpha2` (customs, duties, CUSMA origin).
   */
  madeInCountry: string | null;
  acceptsOffers: boolean;
  /** Integer minor units of `currency`. eBay/Mercari/Poshmark auto-accept threshold. */
  autoAcceptOfferAmount: number | null;
  /** Integer minor units of `currency` (e.g. cents for USD). */
  price: number;
  currency: string;
  location: GeoLocation;
  pickupEnabled: boolean;
  shippingEnabled: boolean;
  shippingProfileId: string | null;
  /** Integer minor units of `currency` — flat per-order shipping price charged at checkout when
   * shippingEnabled. Required (>0) to publish a shipping-enabled listing. */
  shippingFlatAmount: number | null;
  directEnabled: boolean;
  checkoutEnabled: boolean;
  visibilityRadiusKm: number | null;
  riskCategory: RiskCategory;
  createdAt: string;
  updatedAt: string;
}

