/**
 * Scam-risk verdict attached to a chat message at send time.
 *
 * Detection is FAIL-OPEN: a null verdict means "clear OR never evaluated" (detector error,
 * or a message written before this shipped). It is a helper for the humans in the thread,
 * never a safety guarantee, and it never blocks delivery.
 */
export interface MessageRisk {
  level: MessageRiskLevel;
  /** Rule codes from @marka/ai's scam detector, e.g. "external_payment", "gift_card_crypto". */
  codes: string[];
}

