import { z } from "zod";
import { OPENAPI_API_KEY_HEADER, OPENAPI_SERVER_URL, V1_PATH_PREFIX } from "../wire-lite";
import type { JsonValue } from "../contracts";
import { V1_ERROR_STATUS_DESCRIPTIONS, type V1ErrorStatus } from "./errors";
import { V1_COMPONENT_SCHEMAS, V1_ROUTES, type V1ObjectSchema, type V1Route } from "./routes";

/**
 * Renders the v1 route table into an OpenAPI 3.1 document.
 *
 * Pure — no filesystem, no environment. `scripts/generate-openapi.ts` is the thin wrapper that
 * writes the result to apps/docs/openapi/openapi.json.
 *
 * Output is DETERMINISTIC: every object key is emitted in sorted order (see sortKeysDeep), so
 * regenerating without a contract change produces byte-identical bytes and CI can enforce that
 * the committed document matches the schemas.
 */

export const OPENAPI_TITLE = "Marka API";
export const OPENAPI_VERSION = "1.0.0";
export const OPENAPI_SECURITY_SCHEME = "apiKey";
// The origin and the key header are declared in `../wire-lite` (import-free, so a client can use
// them without this file's contract layer) and re-exported here under the same names.
export { OPENAPI_API_KEY_HEADER, OPENAPI_SERVER_URL };

/**
 * States the whole authentication story, because the header alone under-describes it: the key is
 * the primary credential and the only one a generated client sends, but the endpoints also honour
 * a signed-in browser cookie so a seller can explore their own API from a logged-in tab. Keeping
 * this in the document means the published reference matches what the handlers actually accept.
 */
export const OPENAPI_SECURITY_DESCRIPTION =
  `API key created in your Marka account settings, sent as an \`${OPENAPI_API_KEY_HEADER}\` ` +
  "header (an `Authorization: Bearer mk_…` header is accepted as an equivalent spelling). " +
  "Key-authenticated writes additionally require the `api_write` entitlement, which the Pro plan " +
  "and above carry. A signed-in browser session cookie is also accepted for interactive " +
  "exploration from the Marka web app; SDK and server-to-server clients always use a key.";

const COMPONENT_REF_PREFIX = "#/components/schemas/";

/** A JSON value as it appears inside the generated document — the repo's one JSON type. */
export type Json = JsonValue;
export type JsonObject = { [key: string]: Json };

/**
 * Recursively rebuilds an object with its keys sorted, so a change in property-declaration order
 * can never produce a diff. Arrays keep their order — it is semantically meaningful there
 * (`required`, `enum`, `anyOf`, the parameter list). `undefined` entries are dropped, since
 * `JSON.stringify` would drop them anyway and carrying them would make key order observable.
 *
 * Exported for its own unit test: it is the single reason the committed document is byte-stable,
 * and the drift check in CI is only as trustworthy as this function. Reaching it through a whole
 * generated document could not exercise the array-order or undefined cases deliberately.
 */
export function sortKeysDeep(value: Json): Json {
  if (Array.isArray(value)) return value.map(sortKeysDeep);
  if (value === null || typeof value !== "object") return value;
  const sorted: JsonObject = {};
  for (const key of Object.keys(value).sort()) {
    const entry = value[key];
    if (entry !== undefined) sorted[key] = sortKeysDeep(entry);
  }
  return sorted;
}

/**
 * Converts every registered component in ONE pass, so cross-references between them resolve to
 * `#/components/schemas/<Name>` rather than being inlined or renamed to zod's internal
 * `__schemaN` placeholders.
 *
 * `io: "output"` describes what the API emits. Request schemas ride along in the same pass:
 * they deliberately avoid zod `.default()`, so their input and output views are identical and a
 * single conversion is correct for both.
 */
function buildComponentSchemas(): JsonObject {
  const registry = z.registry<{ id: string }>();
  for (const [name, schema] of Object.entries(V1_COMPONENT_SCHEMAS)) {
    registry.add(schema, { id: name });
  }

  const { schemas } = z.toJSONSchema(registry, {
    target: "draft-2020-12",
    io: "output",
    uri: (id: string) => `${COMPONENT_REF_PREFIX}${id}`,
  });

  const components: JsonObject = {};
  for (const [name, schema] of Object.entries(schemas)) {
    // `$schema` and `$id` belong to a standalone JSON Schema document; inside an OpenAPI
    // components map the dialect is declared once at the top level and these are noise.
    const { $schema: _dialect, $id: _id, ...rest } = schema as JsonObject;
    components[name] = rest;
  }
  return components;
}

/** Reverse index from schema instance to component name, for emitting `$ref`s. */
const COMPONENT_NAME_BY_SCHEMA = new Map<z.ZodType, string>(
  Object.entries(V1_COMPONENT_SCHEMAS).map(([name, schema]) => [schema, name]),
);

/** A `$ref` when the schema is a registered component, otherwise an inline conversion. */
function schemaRefOrInline(schema: z.ZodType): JsonObject {
  const name = COMPONENT_NAME_BY_SCHEMA.get(schema);
  if (name !== undefined) return { $ref: `${COMPONENT_REF_PREFIX}${name}` };

  const { $schema: _dialect, ...rest } = z.toJSONSchema(schema, {
    target: "draft-2020-12",
    io: "output",
  }) as JsonObject;
  return rest;
}

/** A schema is optional exactly when it accepts `undefined`. */
function isOptional(schema: z.ZodType): boolean {
  return schema.safeParse(undefined).success;
}

/**
 * Expands a request `params`/`query` object into OpenAPI parameter objects — one per property,
 * required unless the property schema accepts `undefined`.
 */
function buildParameters(schema: V1ObjectSchema, location: "path" | "query"): Json[] {
  return Object.entries(schema.shape)
    .map(([name, propertySchema]) => {
      const parameter: JsonObject = {
        name,
        in: location,
        // Path parameters are required by definition, whatever the property schema allows.
        required: location === "path" ? true : !isOptional(propertySchema),
        schema: schemaRefOrInline(propertySchema),
      };
      const { description } = propertySchema;
      if (description !== undefined) parameter.description = description;
      return parameter;
    })
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));
}

function jsonContent(schema: z.ZodType): JsonObject {
  return { "application/json": { schema: schemaRefOrInline(schema) } };
}

function describeStatus(status: number): string {
  if (status === 200) return "Success";
  if (status === 201) return "Created";
  return V1_ERROR_STATUS_DESCRIPTIONS[status as V1ErrorStatus] ?? "Error";
}

function buildOperation(route: V1Route): JsonObject {
  const operation: JsonObject = {
    operationId: route.operationId,
    summary: route.summary,
    tags: [...route.tags],
    // Restated per operation rather than left to the document-level default, so an operation
    // extracted on its own still carries its credential requirement. `V1Security` has a single
    // member (see routes.ts) — a route that needs none would be an explicit empty array here.
    security: [{ [OPENAPI_SECURITY_SCHEME]: [] }],
  };

  const parameters: Json[] = [
    ...(route.request.params ? buildParameters(route.request.params, "path") : []),
    ...(route.request.query ? buildParameters(route.request.query, "query") : []),
  ];
  if (parameters.length > 0) operation.parameters = parameters;

  if (route.request.body) {
    operation.requestBody = { required: true, content: jsonContent(route.request.body) };
  }

  const responses: JsonObject = {};
  for (const status of Object.keys(route.responses)
    .map(Number)
    .sort((a, b) => a - b)) {
    const schema = route.responses[status];
    if (!schema) continue;
    responses[String(status)] = {
      description: describeStatus(status),
      content: jsonContent(schema),
    };
  }
  operation.responses = responses;

  return operation;
}

/** Assembles the whole OpenAPI 3.1 document from `V1_ROUTES`. */
export function buildOpenApiDocument(): JsonObject {
  const paths: JsonObject = {};
  for (const route of V1_ROUTES) {
    const existing = paths[route.path];
    // Two routes can share a path (GET and PATCH on /v1/listings/{id}) — merge into one path item.
    const pathItem: JsonObject =
      existing !== undefined &&
      existing !== null &&
      typeof existing === "object" &&
      !Array.isArray(existing)
        ? existing
        : {};
    pathItem[route.method] = buildOperation(route);
    paths[route.path] = pathItem;
  }

  const document: JsonObject = {
    openapi: "3.1.0",
    info: {
      title: OPENAPI_TITLE,
      version: OPENAPI_VERSION,
      description:
        "The Marka seller API. Authenticate with an API key created in your Marka account " +
        `settings and sent as an \`${OPENAPI_API_KEY_HEADER}\` header. All monetary amounts are ` +
        "integer minor units of the accompanying currency (e.g. cents for USD).",
    },
    // Origin + mount point, so `servers[0].url` + a `/v1/…` path composes to the URL that is
    // actually served. The server URL alone would send every generated client to `/v1/…`, which
    // 404s.
    servers: [{ url: `${OPENAPI_SERVER_URL}${V1_PATH_PREFIX}` }],
    security: [{ [OPENAPI_SECURITY_SCHEME]: [] }],
    components: {
      securitySchemes: {
        [OPENAPI_SECURITY_SCHEME]: {
          type: "apiKey",
          in: "header",
          name: OPENAPI_API_KEY_HEADER,
          description: OPENAPI_SECURITY_DESCRIPTION,
        },
      },
      schemas: buildComponentSchemas(),
    },
    paths,
  };

  return sortKeysDeep(document) as JsonObject;
}

/** The exact bytes written to disk: 2-space indent, trailing newline. */
export function renderOpenApiJson(): string {
  return `${JSON.stringify(buildOpenApiDocument(), null, 2)}\n`;
}
