import { z } from "zod";

/**
 * The buyer's shipping contact as captured by Stripe Checkout, stored on
 * `Order.checkoutShippingDetails` (CHECKOUT rail, SHIPPING fulfillment only; null otherwise).
 *
 * Field names follow Stripe's `Checkout.Session.shipping_details` verbatim (snake_case
 * `postal_code`, bare `country`) so the stored value is recognisably the Stripe object and a
 * reader can cross-check it against a Checkout Session without a mapping table. `email` and
 * `phone` are NOT part of Stripe's shipping_details — they come from `customer_details` — and
 * are merged in by the webhook so the seller's label flow has a real contact.
 *
 * This is PII. It exists so a seller can buy a shipping label; never log it.
 */
export const CheckoutShippingAddressSchema = z.object({
  line1: z.string().nullable(),
  line2: z.string().nullable(),
  city: z.string().nullable(),
  state: z.string().nullable(),
  postal_code: z.string().nullable(),
  country: z.string().nullable(),
});
export type CheckoutShippingAddress = z.infer<typeof CheckoutShippingAddressSchema>;

export const CheckoutShippingDetailsSchema = z.object({
  name: z.string().nullable(),
  email: z.string().nullable(),
  phone: z.string().nullable(),
  address: CheckoutShippingAddressSchema,
});
export type CheckoutShippingDetails = z.infer<typeof CheckoutShippingDetailsSchema>;

// Stripe's SDK types every address field as `string | null`, but the wire object can omit keys
// (older API versions, test fixtures, rows written before email/phone were merged in). Accept
// `undefined` on input and canonicalise it to `null` so the stored shape is always complete.
const LenientCheckoutShippingDetailsSchema = z.object({
  name: z.string().nullish(),
  email: z.string().nullish(),
  phone: z.string().nullish(),
  address: z.object({
    line1: z.string().nullish(),
    line2: z.string().nullish(),
    city: z.string().nullish(),
    state: z.string().nullish(),
    postal_code: z.string().nullish(),
    country: z.string().nullish(),
  }),
});

/**
 * Validate an untrusted value (a queue payload, a Stripe object, a DB row) into the canonical
 * shape. Throws a ZodError on anything that is not a Stripe-shaped shipping_details object —
 * deliberately loud: a silently-accepted malformed blob is what let the label-destination guard
 * in apps/web/app/api/shipping/labels/route.ts go dead.
 */
export function parseCheckoutShippingDetails(value: unknown): CheckoutShippingDetails {
  const lenient = LenientCheckoutShippingDetailsSchema.parse(value);
  return {
    name: lenient.name ?? null,
    email: lenient.email ?? null,
    phone: lenient.phone ?? null,
    address: {
      line1: lenient.address.line1 ?? null,
      line2: lenient.address.line2 ?? null,
      city: lenient.address.city ?? null,
      state: lenient.address.state ?? null,
      postal_code: lenient.address.postal_code ?? null,
      country: lenient.address.country ?? null,
    },
  };
}
