import { z } from "zod";
import {
  INVENTORY_TYPES,
  LISTING_AUTHORITIES,
  LISTING_CONDITIONS,
  LISTING_STATUSES,
  RISK_CATEGORIES,
} from "../enums";
import {
  CATEGORY_PATH_MESSAGE,
  CATEGORY_PATH_PATTERN,
  DEFAULT_CATEGORY_PATH,
  LISTING_TITLE_MAX_LENGTH,
  isPlausibleCategoryPath,
} from "../contracts";
import {
  V1GeoLocationSchema,
  V1ImageUrlSchema,
  V1IsoDateTimeSchema,
  V1JsonValueSchema,
  V1PackageDimensionsMmSchema,
  V1PaginationFields,
  V1PaginationQuerySchema,
  v1MinorUnits,
  v1NullableMinorUnits,
} from "./common";

const MADE_IN_COUNTRY_DESCRIPTION =
  "Country of manufacture as an ISO 3166-1 alpha-2 code (e.g. CA, DE), stored uppercase; null " +
  "when not specified. Used as the item's origin country on international shipping labels " +
  "(customs and duties).";

/**
 * `madeInCountry` on a write: the shape only (two characters). Whether it names a real country is
 * the domain's call (`invalid_made_in_country`, a 400 at every door), so the sell form, the v1 API
 * and the AI tools all share the one list in `@marka/shared` and the one rule in `@marka/domain`.
 * Lowercase is accepted and stored uppercase; null clears it on an update.
 */
export const V1MadeInCountryInputSchema = z
  .string()
  .length(2)
  .nullable()
  .optional()
  .describe(
    `${MADE_IN_COUNTRY_DESCRIPTION} A lowercase code is accepted and uppercased; an unknown ` +
      "code is rejected. On an update, null clears it and omitting the field leaves it unchanged.",
  );

/**
 * The canonical listing as `/v1/*` returns it. Field-for-field mirror of the `Listing` interface
 * in ../contracts.ts — nullable exactly where the domain type is nullable, integer minor units
 * for every amount. No computed or convenience fields are invented here: what the repositories
 * build (buildListingFromRow) is what ships.
 */
export const V1ListingSchema = z.object({
  id: z.string(),
  sellerAccountId: z.string(),
  authority: z.enum(LISTING_AUTHORITIES),
  status: z.enum(LISTING_STATUSES),
  inventoryType: z.enum(INVENTORY_TYPES),
  quantityTotal: z.int().nonnegative(),
  quantityReserved: z.int().nonnegative(),
  categoryPath: z.string(),
  condition: z.enum(LISTING_CONDITIONS),
  title: z.string(),
  description: z.string(),
  attributes: V1JsonValueSchema,
  imageUrls: z.array(z.string()),
  brand: z.string().nullable(),
  gtin: z.string().nullable().describe("UPC, EAN, ISBN or other GTIN — digits only."),
  packageWeightGrams: z.int().nonnegative().nullable(),
  packageDimensionsMm: V1PackageDimensionsMmSchema.nullable(),
  madeInCountry: z.string().nullable().describe(MADE_IN_COUNTRY_DESCRIPTION),
  acceptsOffers: z.boolean(),
  autoAcceptOfferAmount: v1NullableMinorUnits(
    "Offers at or above this amount are auto-accepted. Integer minor units.",
  ),
  price: v1MinorUnits("Integer minor units of `currency` (e.g. cents for USD)."),
  currency: z.string().describe("ISO 4217 currency code."),
  location: V1GeoLocationSchema,
  pickupEnabled: z.boolean(),
  shippingEnabled: z.boolean(),
  shippingProfileId: z.string().nullable(),
  shippingFlatAmount: v1NullableMinorUnits(
    "Flat per-order shipping charged at checkout. Integer minor units of `currency`.",
  ),
  directEnabled: z
    .boolean()
    .describe("Available on the DIRECT rail (in-person pickup, no Stripe)."),
  checkoutEnabled: z.boolean().describe("Available on the CHECKOUT rail (Stripe Connect payment)."),
  visibilityRadiusKm: z.number().positive().nullable(),
  riskCategory: z.enum(RISK_CATEGORIES),
  createdAt: V1IsoDateTimeSchema,
  updatedAt: V1IsoDateTimeSchema,
});
export type V1Listing = z.infer<typeof V1ListingSchema>;

/**
 * Body for `POST /v1/listings`. Only the fields a draft genuinely needs are required; every
 * other field carries a server-side default (see buildCreateListingDraftInput in
 * apps/web/lib/listing-draft-input.ts) and is omitted rather than given a zod `.default()`, so
 * the request and response views of this schema are identical.
 *
 * `.strict()`: an unknown key is a 400, not silently dropped. A caller who misspells a field, or
 * reaches for one this endpoint does not accept (`status`, `quantityReserved`), is told so —
 * rather than getting a 200 and a listing that quietly ignored half the request.
 */
export const V1CreateListingRequestSchema = z
  .object({
    title: z.string().min(1).max(LISTING_TITLE_MAX_LENGTH),
    description: z.string(),
    price: v1MinorUnits("Integer minor units of `currency` (e.g. cents for USD)."),
    currency: z
      .string()
      .length(3)
      .optional()
      .describe("ISO 4217 code. Defaults to the platform default currency."),
    // .regex before .refine on purpose: the pattern serializes into the OpenAPI document as a
    // machine-readable constraint, while the refine carries the numeric-segment and length clauses
    // the pattern cannot express. Both name themselves, so a 400 says which rule was broken.
    categoryPath: z
      .string()
      .regex(CATEGORY_PATH_PATTERN, {
        message:
          "Must be lowercase alphanumeric parts joined by '-' or '/', with no leading or " +
          "trailing separator.",
      })
      .refine(isPlausibleCategoryPath, {
        message: CATEGORY_PATH_MESSAGE,
      })
      .optional()
      .describe(
        'Slash-delimited lowercase taxonomy path, e.g. "electronics/cameras" — never an external ' +
          `marketplace's numeric category id. Defaults to "${DEFAULT_CATEGORY_PATH}".`,
      ),
    condition: z.enum(LISTING_CONDITIONS).optional().describe('Defaults to "good".'),
    inventoryType: z.enum(INVENTORY_TYPES).optional().describe('Defaults to "unique".'),
    quantityTotal: z.int().positive().optional().describe("Defaults to 1."),
    attributes: V1JsonValueSchema.optional(),
    location: V1GeoLocationSchema.optional(),
    madeInCountry: V1MadeInCountryInputSchema,
    pickupEnabled: z.boolean().optional(),
    shippingEnabled: z.boolean().optional(),
    shippingProfileId: z.string().nullable().optional(),
    shippingFlatAmount: v1NullableMinorUnits(
      "Integer minor units. Must be greater than 0 before a shipping-enabled listing can be " +
        "published.",
    ).optional(),
    directEnabled: z.boolean().optional(),
    checkoutEnabled: z.boolean().optional(),
    visibilityRadiusKm: z.number().positive().nullable().optional(),
    riskCategory: z.enum(RISK_CATEGORIES).optional().describe('Defaults to "general".'),
  })
  .strict();
export type V1CreateListingRequest = z.infer<typeof V1CreateListingRequestSchema>;

/**
 * Body for `PATCH /v1/listings/{id}` — a partial field update. Lifecycle transitions are NOT
 * expressed here: publishing is `POST /v1/listings/{id}/publish`, which runs the domain guards
 * (activateListing) that a bare status write would bypass.
 *
 * `.strict()` is what MAKES that true. Without it zod strips unknown keys, so `{"status":"active"}`
 * parsed clean, updated nothing, and answered 200 — a caller reaching for the lifecycle through
 * this endpoint was told it had worked. Now the same body is a 400 that names the offending key,
 * pointing at the publish endpoint instead of silently doing nothing.
 *
 * Every field is optional, so `{}` is a legal (no-op) request. That is deliberate: which fields
 * are present IS the update, and demanding at least one would make a client that diffs its local
 * state have to special-case "nothing changed".
 */
export const V1UpdateListingRequestSchema = z
  .object({
    title: z.string().min(1).max(LISTING_TITLE_MAX_LENGTH).optional(),
    description: z.string().optional(),
    price: v1MinorUnits("Integer minor units of the listing's currency.").optional(),
    imageUrls: z
      .array(V1ImageUrlSchema)
      .optional()
      .describe(
        "Absolute http(s) image URLs in display order; the first is the cover. Replaces the whole " +
          "list. Only URLs under Marka's media storage are linked to the listing's photo assets " +
          "(the cover image on market and seller pages); any other host is stored but not shown.",
      ),
    madeInCountry: V1MadeInCountryInputSchema,
    pickupEnabled: z.boolean().optional(),
    shippingEnabled: z.boolean().optional(),
    directEnabled: z.boolean().optional(),
    checkoutEnabled: z.boolean().optional(),
  })
  .strict();
export type V1UpdateListingRequest = z.infer<typeof V1UpdateListingRequestSchema>;

export const V1ListingIdParamsSchema = z.object({
  id: z.string().min(1).describe("Listing id."),
});
export type V1ListingIdParams = z.infer<typeof V1ListingIdParamsSchema>;

export const V1ListListingsQuerySchema = V1PaginationQuerySchema;
export type V1ListListingsQuery = z.infer<typeof V1ListListingsQuerySchema>;

export const V1ListListingsResponseSchema = z.object({
  listings: z.array(V1ListingSchema),
  ...V1PaginationFields,
});
export type V1ListListingsResponse = z.infer<typeof V1ListListingsResponseSchema>;

export const V1ListingResponseSchema = z.object({
  listing: V1ListingSchema,
});
export type V1ListingResponse = z.infer<typeof V1ListingResponseSchema>;
