import { MCPServer } from "@mastra/mcp";
import { createTool } from "@mastra/core/tools";
import {
  OPENAPI_API_KEY_HEADER,
  OPENAPI_SERVER_URL,
  V1_PATH_PREFIX,
  trimTrailingSlashes,
  V1CreateListingRequestSchema,
  V1UpdateListingRequestSchema,
  z,
} from "@marka/shared";
// The package's own version, for the MCP `serverInfo`. A named import from JSON so esbuild inlines
// ONLY this one string into the published dist (tsup tree-shakes the rest of package.json away) and
// nothing reads a file at runtime — the published package.json is a different file in a different
// place from this one, which is why no `readFileSync` and no `../package.json` path survives the
// build. The source is the workspace manifest, which is what scripts/release-sdk.mjs publishes.
import { version as SDK_VERSION } from "../package.json";
import { MarkaApiError } from "./errors";
import { MarkaClient } from "./client";

/**
 * A local MCP server over the public v1 API, plus the config snippets that point an MCP client at
 * Marka.
 *
 * Every tool below calls a {@link MarkaClient} method — no tool builds a URL, a path, or a header
 * of its own. That is deliberate: the `/api` mount point is encoded exactly once (in the client,
 * from `V1_PATH_PREFIX`), so this file cannot become a second place where the API's shape is
 * restated and later drifts from it.
 *
 * WHY THE TOOL LIST DIFFERS FROM THE REMOTE `/api/mcp` SERVER
 * The hosted server (apps/ai/src/mastra/mcp.ts) exposes search_listings, get_listing,
 * list_categories, get_seller_info, create_listing_draft and update_listing_draft, backed by
 * direct database reads. This server is backed by the public v1 HTTP API, which has no seller
 * endpoint at all — so rather than invent one, `get_seller_info` is replaced by `get_me`, the
 * thing v1 actually answers (who this key is, and whether its plan carries `api_write`, which is
 * what lets an agent explain a 402 instead of retrying into it). The two write tools are named
 * for the endpoints they call. Orders (`GET /v1/orders`) are deliberately NOT exposed: an order
 * carries the buyer's checkout contact details, and handing that to an arbitrary MCP client by
 * default is not a decision this package should make for a seller.
 */

/**
 * The MCP gateway's path. Same Next `/api` mount as the v1 routes, so it composes from the one
 * shared constant rather than restating the prefix.
 */
const MCP_HTTP_PATH = `${V1_PATH_PREFIX}/mcp`;

/**
 * The `bin` this package declares, which is what Claude Desktop spawns for the stdio bridge.
 *
 * It resolves as a bare command wherever @joinmarka/sdk is installed — from npm, inside this
 * monorepo, or from a checkout. Without an install, `npx -p @joinmarka/sdk marka-mcp-stdio` fetches
 * the package and runs the same bin; a checkout points `bridgeCommand` at the file instead.
 */
export const MARKA_MCP_STDIO_BIN = "marka-mcp-stdio";

export interface MarkaMcpOptions {
  /** An API key created in Marka account settings (`mk_…`). */
  readonly apiKey: string;
  /** API origin — scheme and host only, e.g. `http://localhost:3001`. Defaults to production. */
  readonly baseUrl?: string | undefined;
  /** Injectable transport, forwarded to the underlying {@link MarkaClient}. Tests use this. */
  readonly fetch?: typeof globalThis.fetch | undefined;
}

export interface MarkaMcpConfigOptions {
  readonly apiKey: string;
  readonly baseUrl?: string | undefined;
  /**
   * How Claude Desktop should launch the stdio bridge, as `[command, ...args]`. Defaults to the
   * `marka-mcp-stdio` bin, which resolves once @joinmarka/sdk is installed. Without an install,
   * pass `["npx", "-p", "@joinmarka/sdk", "marka-mcp-stdio"]`; from a checkout, pass
   * `["node", "/abs/path/to/packages/sdk/bin/mcp-stdio.mjs"]`.
   */
  readonly bridgeCommand?: readonly string[] | undefined;
}

/** A `mcpServers` block for a client that speaks streamable HTTP natively. */
export interface MarkaHttpMcpConfig {
  readonly mcpServers: {
    readonly marka: {
      readonly type: "http";
      readonly url: string;
      readonly headers: Readonly<Record<string, string>>;
    };
  };
}

/**
 * A `mcpServers` block for a client that speaks streamable HTTP AND OAuth — no credential in the
 * file at all. The client discovers the authorization server from the gateway's 401 challenge,
 * registers itself, opens a browser, and stores the token it gets back.
 */
export interface MarkaOAuthMcpConfig {
  readonly mcpServers: {
    readonly marka: {
      readonly type: "http";
      readonly url: string;
    };
  };
}

/** A `mcpServers` block for claude_desktop_config.json, which spawns a stdio subprocess. */
export interface MarkaStdioMcpConfig {
  readonly mcpServers: {
    readonly marka: {
      readonly command: string;
      readonly args: readonly string[];
      readonly env: Readonly<Record<string, string>>;
    };
  };
}

export interface MarkaMcpServerConfig {
  /** Paste into any client that connects to a remote MCP server over streamable HTTP. */
  readonly http: MarkaHttpMcpConfig;
  /** Paste into claude_desktop_config.json, which has no HTTP transport and spawns a command. */
  readonly claudeDesktop: MarkaStdioMcpConfig;
}

/** Trailing slashes would produce `//api/mcp`, which some proxies redirect and others 404. */
function normalizeOrigin(baseUrl: string | undefined): string {
  return trimTrailingSlashes(baseUrl ?? OPENAPI_SERVER_URL);
}

/**
 * Ready-to-paste MCP client configuration for both transports.
 *
 * The HTTP form points at Marka's hosted gateway (`/api/mcp`) — the richer, database-backed
 * server. The Claude Desktop form runs THIS package's local server over stdio, because
 * claude_desktop_config.json cannot dial an HTTP MCP server directly.
 */
export function getMcpServerConfig(options: MarkaMcpConfigOptions): MarkaMcpServerConfig {
  const origin = normalizeOrigin(options.baseUrl);
  const [command = MARKA_MCP_STDIO_BIN, ...args] = options.bridgeCommand ?? [];

  return {
    http: {
      mcpServers: {
        marka: {
          type: "http",
          url: `${origin}${MCP_HTTP_PATH}`,
          headers: { [OPENAPI_API_KEY_HEADER]: options.apiKey },
        },
      },
    },
    claudeDesktop: {
      mcpServers: {
        marka: {
          command,
          args,
          env: {
            MARKA_API_KEY: options.apiKey,
            ...(options.baseUrl === undefined ? {} : { MARKA_BASE_URL: origin }),
          },
        },
      },
    },
  };
}

/**
 * The same hosted gateway, with nothing to paste.
 *
 * This is the configuration to reach for first. `getMcpServerConfig` puts an API key in a header,
 * which means a long-lived secret sitting in a config file; this one carries no credential, and the
 * token the client ends up holding is short-lived, refreshable, and revocable by its owner from
 * Settings → Connected apps. Keys remain the right answer for a script or a CI job, where there is
 * no browser to open.
 *
 * Deliberately additive rather than a change to `getMcpServerConfig`: 0.1.0 is published, and
 * consumers depend on its shape.
 */
export function getMcpOAuthServerConfig(
  options: { readonly baseUrl?: string | undefined } = {},
): MarkaOAuthMcpConfig {
  return {
    mcpServers: {
      marka: { type: "http", url: `${normalizeOrigin(options.baseUrl)}${MCP_HTTP_PATH}` },
    },
  };
}

/**
 * The write tools' inputs are NARROWED VIEWS of the request contracts, not re-typed copies —
 * `.pick()` keeps each field's type and its `.describe()` text (which is what the model actually
 * reads), so renaming a contract field breaks the build here instead of silently dropping it from
 * every tool call.
 *
 * The read tools stay hand-written on purpose: their query contracts are built from
 * `z.coerce`/`z.stringbool` to parse query-STRING text, and a tool receives typed JSON — reusing
 * them would tell the model to send `"true"` where it should send `true`.
 *
 * Deriving these is cheap — 184k type instantiations against 182k for hand-written equivalents —
 * but ONLY while this package resolves a single zod. When it briefly resolved two (see the
 * `zod` dependency in package.json, which exists to prevent exactly that), the picked views
 * flowing into `createTool`'s generic inference cost 47.5M instantiations and killed tsc with
 * TS2589. If that error ever reappears here, suspect duplicate zod copies before suspecting the
 * schemas: `pnpm --filter @joinmarka/sdk why zod` should report one version.
 *
 * The chosen field set is what a listing needs to be publishable, because the defaults make
 * everything else a dead end: `buildCreateListingDraftInput` defaults all four fulfilment/rail
 * flags to `false`, while `activateListing` demands pickup-or-shipping AND direct-or-checkout,
 * plus a positive `shippingFlatAmount` whenever shipping is on. Omitting the rail flags would
 * have made every draft this tool creates impossible to publish without a visit to the web UI.
 */
const createListingInput = V1CreateListingRequestSchema.pick({
  title: true,
  description: true,
  price: true,
  currency: true,
  categoryPath: true,
  quantityTotal: true,
  pickupEnabled: true,
  shippingEnabled: true,
  shippingFlatAmount: true,
  directEnabled: true,
  checkoutEnabled: true,
});

const updateListingInput = V1UpdateListingRequestSchema.pick({
  title: true,
  description: true,
  price: true,
  pickupEnabled: true,
  shippingEnabled: true,
  directEnabled: true,
  checkoutEnabled: true,
}).extend({ id: z.string().min(1).describe("The listing id.") });

/**
 * Builds the six tools over one client instance, so every call shares the same key, origin and
 * transport.
 */
function buildTools(client: MarkaClient) {
  return {
    search_listings: createTool({
      id: "search_listings",
      description:
        "Search active Marka listings by text, location, price band and fulfilment options. " +
        "Prices are integer minor units of the returned currency.",
      inputSchema: z.object({
        q: z.string().optional().describe("Free-text query. Omit to browse."),
        city: z.string().optional().describe("City to anchor a radius search on."),
        radiusKm: z.number().positive().optional().describe("Radius around `city`, in km."),
        pickup: z.boolean().optional().describe("Only listings offering local pickup."),
        shipping: z.boolean().optional().describe("Only listings offering shipping."),
        minPrice: z.number().int().nonnegative().optional().describe("Integer minor units."),
        maxPrice: z.number().int().nonnegative().optional().describe("Integer minor units."),
        limit: z.number().int().min(1).max(100).optional(),
        offset: z.number().int().min(0).optional(),
      }),
      execute: async (inputData) => client.search(inputData),
    }),

    get_listing: createTool({
      id: "get_listing",
      description: "Fetch one listing by id. Answers `{ found: false }` when there is no such id.",
      inputSchema: z.object({ id: z.string().describe("The listing id.") }),
      execute: async (inputData) => {
        try {
          const { listing } = await client.getListing(inputData.id);
          return { found: true, listing };
        } catch (error) {
          // error-surfaced: "no such listing" is an ANSWER for a caller that asked whether one
          // exists, not a fault — an LLM handles a `found: false` far better than a thrown 404.
          // Every other failure (401, 429, a transport error) still propagates untouched.
          if (error instanceof MarkaApiError && error.status === 404) return { found: false };
          throw error;
        }
      },
    }),

    list_categories: createTool({
      id: "list_categories",
      description: "List the categories active listings are filed under, most populated first.",
      inputSchema: z.object({
        limit: z.number().int().min(1).max(50).optional(),
      }),
      execute: async (inputData) => client.listCategories(inputData),
    }),

    get_me: createTool({
      id: "get_me",
      description:
        "Identify the account behind the API key and report its plan. Check for the `api_write` " +
        "entitlement before attempting a write: without it, writes answer 402.",
      inputSchema: z.object({}),
      execute: async () => client.getMe(),
    }),

    create_listing: createTool({
      id: "create_listing",
      description:
        "Create a DRAFT listing. Drafts are not visible to buyers until they are published, " +
        "which is a separate step this server deliberately does not expose. `price` is integer " +
        "minor units (e.g. 4500 = $45.00). To leave the draft publishable, set at least one of " +
        "pickupEnabled/shippingEnabled AND at least one of directEnabled (in-person handoff, no " +
        "card) / checkoutEnabled (card payment, requires the seller's Stripe account); every one " +
        "of these defaults to false. Shipping additionally needs a shippingFlatAmount above 0.",
      inputSchema: createListingInput,
      execute: async (inputData) => client.createListing(inputData),
    }),

    update_listing: createTool({
      id: "update_listing",
      description:
        "Update fields on an existing listing. Does not change its lifecycle state — publishing " +
        "is a separate step this server deliberately does not expose. Note that the update " +
        "contract carries no shippingFlatAmount, so a listing that needs one must be given it at " +
        "creation or edited in the web app.",
      inputSchema: updateListingInput,
      execute: async (inputData) => {
        const { id, ...fields } = inputData;
        return client.updateListing(id, fields);
      },
    }),

    // No publish_listing — publishing requires in-app HITL confirmation.
  };
}

/**
 * An MCP server exposing Marka's public API as tools, backed entirely by {@link MarkaClient}.
 *
 * Unlike the hosted gateway this runs in the CALLER's process against their own key, so the
 * error-redaction proxy that apps/ai/src/mastra/mcp.ts wraps its tools in is not repeated here:
 * there is no second party to leak to, and flattening a failure would cost the caller the status
 * and code (`entitlement_required`, `rate_limited`) their client needs to explain what went wrong.
 */
export function createMarkaMcpServer(options: MarkaMcpOptions): MCPServer {
  const client = new MarkaClient({
    apiKey: options.apiKey,
    baseUrl: options.baseUrl,
    fetch: options.fetch,
  });

  return new MCPServer({
    id: "marka",
    name: "Marka",
    version: SDK_VERSION,
    description: "Search Marka listings and draft new ones through the public Marka API.",
    tools: buildTools(client),
  });
}
