import { z } from "zod";

/**
 * The single error envelope every non-2xx `/v1/*` response uses.
 *
 * Shape is taken from what the web API already returns: `toApiError`
 * (apps/web/lib/api-errors.ts) emits `{ error, code }` for a DomainError and `{ error }` for
 * everything else, and the hand-rolled 401s emit `{ error: "Unauthorized" }`.
 *
 * `code` is a free-form string, NOT an enum: it carries the originating DomainError code
 * (e.g. "subscription.tier_too_low", "listing.authority_locked") and new codes are added by
 * domain work without a contract change. Clients should branch on the HTTP status first and
 * treat `code` as a refinement.
 */
export const V1ErrorSchema = z.object({
  /** Human-readable message. Never contains provider internals — see toApiError. */
  error: z.string(),
  /** Originating DomainError / Prisma code when one applies. */
  code: z.string().optional(),
});
export type V1Error = z.infer<typeof V1ErrorSchema>;

/**
 * Statuses the v1 surface models. Anything else (502/503 from a failed upstream) is an
 * operational condition, not part of the contract.
 */
export const V1_ERROR_STATUSES = [400, 401, 402, 403, 404, 429] as const;
export type V1ErrorStatus = (typeof V1_ERROR_STATUSES)[number];

/** What each modeled status means on this API. Used for the OpenAPI response descriptions. */
export const V1_ERROR_STATUS_DESCRIPTIONS: Readonly<Record<V1ErrorStatus, string>> = {
  400: "Validation failed — the request body or query did not match the schema.",
  401: "Missing, malformed, or revoked API key.",
  402: "The API key's plan does not carry the entitlement this endpoint requires.",
  403: "Authenticated, but not permitted to act on this resource.",
  404: "No such resource, or it is not visible to this key.",
  429: "Rate limit exceeded for this API key.",
};
