/**
 * Colour-theme choice (DECISIONS #28). Lives here rather than in `@marka/db` so the client-side
 * toggle can import the type without pulling Prisma into the browser bundle. `system` means "no
 * explicit choice" — no `data-theme` attribute is stamped and CSS `prefers-color-scheme` decides.
 */
export const THEME_PREFERENCES = ["system", "light", "dark"] as const;
export type ThemePreference = (typeof THEME_PREFERENCES)[number];

/** Narrow arbitrary input (a cookie value, a form field, a DB enum) to a preference, else null. */
export function parseThemePreference(value: unknown): ThemePreference | null {
  return typeof value === "string" && (THEME_PREFERENCES as readonly string[]).includes(value)
    ? (value as ThemePreference)
    : null;
}

