import { z } from "zod";

/**
 * Category listing. Marka has no category TABLE — categories are the distinct `categoryPath`
 * values across ACTIVE listings, grouped and counted (see listCategoriesImpl in
 * apps/ai/src/mastra/tools/list-categories.ts). `label` is the human-readable rendering of the
 * path via formatCategoryLabel; `count` is how many active listings carry it.
 *
 * The set is small and has no second page: `limit` truncates the tail of a single count-ordered
 * list, so a larger one does not surface different categories, it only truncates less.
 */
export const V1CategorySchema = z.object({
  categoryPath: z.string(),
  label: z.string(),
  count: z.int().nonnegative(),
});
export type V1Category = z.infer<typeof V1CategorySchema>;

export const V1_CATEGORIES_MAX_LIMIT = 50;

export const V1ListCategoriesQuerySchema = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(V1_CATEGORIES_MAX_LIMIT)
    .optional()
    .describe(
      `How many categories to return, 1-${V1_CATEGORIES_MAX_LIMIT}. Defaults to ` +
        `${V1_CATEGORIES_MAX_LIMIT}, which returns the whole set unless more than ` +
        `${V1_CATEGORIES_MAX_LIMIT} categories carry active listings — there is no second page, ` +
        "so a lower limit only truncates the tail, it never surfaces different categories.",
    ),
});
export type V1ListCategoriesQuery = z.infer<typeof V1ListCategoriesQuerySchema>;

/** Ordered by `count`, descending. */
export const V1ListCategoriesResponseSchema = z.object({
  categories: z.array(V1CategorySchema),
});
export type V1ListCategoriesResponse = z.infer<typeof V1ListCategoriesResponseSchema>;
