import { z } from "zod";
import {
  DISPUTE_STATES,
  FULFILLMENT_MODES,
  ORDER_RAILS,
  ORDER_STATUSES,
  PROTECTION_TIERS,
  REVIEW_ELIGIBILITY_STATES,
} from "../enums";
import { CheckoutShippingDetailsSchema } from "../checkout-shipping-details";
import {
  V1IsoDateTimeSchema,
  V1MoneyBreakdownSchema,
  V1PaginationFields,
  V1PaginationQuerySchema,
} from "./common";
import { V1ListingSchema } from "./listings";

/**
 * A seller's order, read-only on v1. Mirrors the `Order` interface in ../contracts.ts as built
 * by buildOrderFromRow (packages/db/src/repositories/order.ts).
 *
 * On buyer data: there are no dedicated top-level buyer email/name fields — the buyer is
 * identified by the opaque `buyerId` that the seller dashboard already renders as "Buyer ID"
 * (apps/web/app/[locale]/sell/orders/[id]/page.tsx). Buyer CONTACT DETAILS are nonetheless
 * exposed, by design, inside `checkoutShippingDetails`: on the CHECKOUT rail that blob
 * carries the name, email, phone and address the buyer supplied at checkout, and the shipping
 * flow reads exactly those fields to buy a label
 * (apps/web/app/[locale]/sell/orders/[id]/shipping/page.tsx). A seller cannot ship without
 * them, so this is deliberate passthrough rather than a leak — but treat the field as PII and
 * do not log it.
 */
export const V1OrderSchema = z.object({
  id: z.string(),
  listingId: z.string(),
  buyerId: z.string(),
  sellerAccountId: z.string(),
  connectedAccountId: z.string().nullable(),
  quantity: z.int().positive(),
  rail: z.enum(ORDER_RAILS),
  fulfillmentMode: z.enum(FULFILLMENT_MODES),
  protectionTier: z.enum(PROTECTION_TIERS),
  status: z.enum(ORDER_STATUSES),
  listingSnapshot: V1ListingSchema.describe(
    "Immutable copy of the listing as it was when the order was placed.",
  ),
  priceSnapshot: V1MoneyBreakdownSchema.describe("Immutable price breakdown, integer minor units."),
  stripeCheckoutSessionId: z.string().nullable(),
  checkoutShippingDetails: CheckoutShippingDetailsSchema.nullable().describe(
    "Buyer-supplied shipping contact from Stripe Checkout: name, email, phone and the postal " +
      "address (Stripe field names, e.g. `postal_code`), which the seller needs to buy a " +
      "shipping label. Contains personal data: handle accordingly and do not log it. Null on " +
      "the DIRECT (pickup) rail and on non-shipping orders.",
  ),
  paymentId: z.string().nullable(),
  pickupSessionId: z.string().nullable(),
  shipmentId: z.string().nullable(),
  reviewEligibilityState: z.enum(REVIEW_ELIGIBILITY_STATES),
  disputeState: z.enum(DISPUTE_STATES),
  createdAt: V1IsoDateTimeSchema,
  updatedAt: V1IsoDateTimeSchema,
});
export type V1Order = z.infer<typeof V1OrderSchema>;

export const V1OrderIdParamsSchema = z.object({
  id: z.string().min(1).describe("Order id."),
});
export type V1OrderIdParams = z.infer<typeof V1OrderIdParamsSchema>;

export const V1ListOrdersQuerySchema = z.object({
  status: z
    .enum(ORDER_STATUSES)
    .optional()
    .describe("Restrict to a single order status. Omit for all statuses."),
  ...V1PaginationQuerySchema.shape,
});
export type V1ListOrdersQuery = z.infer<typeof V1ListOrdersQuerySchema>;

/** Newest first, matching getOrdersForSeller. */
export const V1ListOrdersResponseSchema = z.object({
  orders: z.array(V1OrderSchema),
  ...V1PaginationFields,
});
export type V1ListOrdersResponse = z.infer<typeof V1ListOrdersResponseSchema>;

export const V1OrderResponseSchema = z.object({
  order: V1OrderSchema,
});
export type V1OrderResponse = z.infer<typeof V1OrderResponseSchema>;
