import { z } from "zod";
import { V1PaginationFields, V1PaginationQuerySchema } from "./common";
import { V1ListingSchema } from "./listings";

/**
 * A listing as it appears in a search result: the fields a buyer-facing result card needs, not
 * the full record. Callers that need the rest fetch `GET /v1/listings/{id}`.
 *
 * PICKED from V1ListingSchema rather than restated, so a summary field can never describe itself
 * differently from the same field on the full record — the hand-written copy had already drifted
 * (its `price` had lost the "integer minor units" note the canonical one carries). Narrowing the
 * SET of fields is the intent here; redefining any of them is not.
 */
export const V1ListingSummarySchema = V1ListingSchema.pick({
  id: true,
  sellerAccountId: true,
  title: true,
  categoryPath: true,
  condition: true,
  price: true,
  currency: true,
  imageUrls: true,
  pickupEnabled: true,
  shippingEnabled: true,
  location: true,
  createdAt: true,
});
export type V1ListingSummary = z.infer<typeof V1ListingSummarySchema>;

/**
 * How much of the catalogue a search considers: the {@link V1_SEARCH_SCAN_CEILING} most recently
 * listed ACTIVE listings, ranked. An older item is not reachable at any `offset`.
 *
 * This is the size of the candidate set the ranked ids are hydrated from, so it bounds the search
 * on the site and on this API alike — both run the same read. It lives in the contract because a
 * client cannot discover it by paging (a deeper page is empty, not an error), and it is exported
 * so the handler and the candidate load import the one number instead of each repeating it.
 */
export const V1_SEARCH_SCAN_CEILING = 200;

/**
 * `GET /v1/search` query. Booleans and numbers are coerced from query-string text; the OpenAPI
 * document renders them as their logical types.
 *
 * Only filters the search layer actually honours are modeled — `searchTypesense` /
 * `searchListings` (packages/search) support the query text, the pickup/shipping flags, a price
 * band, and an origin+radius geo filter. There is deliberately no facet output: the current
 * search returns ranked listing IDs only, so a `facets` field would be a promise the
 * implementation cannot keep.
 */
export const V1SearchQuerySchema = z.object({
  q: z.string().optional().describe("Free-text query. Omit to browse without a text filter."),
  pickup: z.stringbool().optional().describe("Only listings offering local pickup."),
  shipping: z.stringbool().optional().describe("Only listings offering shipping."),
  city: z
    .string()
    .optional()
    .describe(
      "City to anchor the radius filter on; must match a city present in the catalogue. A city " +
        "that matches none — including one whose listings have all sold — returns no results, " +
        "rather than silently dropping the location filter and answering with the whole country.",
    ),
  radiusKm: z.coerce
    .number()
    .positive()
    .optional()
    .describe("Search radius around `city`, in kilometres. Ignored unless `city` is supplied."),
  minPrice: z.coerce
    .number()
    .int()
    .nonnegative()
    .optional()
    .describe("Lowest acceptable price, in integer minor units."),
  maxPrice: z.coerce
    .number()
    .int()
    .nonnegative()
    .optional()
    .describe("Highest acceptable price, in integer minor units."),
  ...V1PaginationQuerySchema.shape,
  // Overrides the shared pagination description: on search, `offset` has a hard end that the
  // generic "records to skip" wording would not warn a paging client about.
  offset: V1PaginationQuerySchema.shape.offset.describe(
    "Number of results to skip. Defaults to 0. Search covers the " +
      `${V1_SEARCH_SCAN_CEILING} most recently listed active listings, so an offset at or past ` +
      "that ceiling returns an empty page — it does not reach older items.",
  ),
});
export type V1SearchQuery = z.infer<typeof V1SearchQuerySchema>;

export const V1SearchResponseSchema = z.object({
  /** Echo of the query text that produced these results ("" when none was supplied). */
  query: z.string(),
  results: z
    .array(V1ListingSummarySchema)
    .describe(
      `Ranked results, best first, drawn from the ${V1_SEARCH_SCAN_CEILING} most recently listed ` +
        "active listings.",
    ),
  ...V1PaginationFields,
});
export type V1SearchResponse = z.infer<typeof V1SearchResponseSchema>;
